WITH deduped AS (SELECT id, name, country, city, segment, is_active, credit_limit FROM (SELECT *, RANK() OVER (PARTITION BY city ORDER BY signup_date NULLS FIRST) AS latest_rank FROM customers) ranked WHERE latest_rank = 1) SELECT id, name, city, segment, is_active, credit_limit, CASE WHEN name RLIKE '^(Jack Taylor|  Carol Diaz)$' THEN 'GROUP_B' WHEN name RLIKE '^(Alice Wong|bob smith)$' THEN 'PRIORITY' ELSE 'GROUP_A' END AS name_zone FROM deduped ORDER BY credit_limit DESC NULLS LAST;
